 c=['İhracat Genel Müdürlüğünün görüşü alınarak Gümrükler Genel Müdürlüğü', 'İzni veren gümrük idaresinin önerisi üzerine ilgili bölge müdürlüğü',
    'İhracatçı birlikleri genel sekreterliğinin görüşü alınarak Ticaret Bakanlığı', 'Ticaret Bakanlığının teklifi üzerine Cumhurbaşkanı'],
 tuzak=False,
